  const perLookDelta =
    bound === "betting" ? perStratumDelta : perStratumDelta / schedule.length;
  const looks: AdaptiveLook[] = [];
  for (let j = 0; j < schedule.length; j++) {
    const n = schedule[j]!;
    const flips = await flipsPrefix(n);
    const upper =
      bound === "betting"
        ? bettingUpperBound(flips, perLookDelta)
        : bound === "wor"
          ? worUpperBound(flips, perLookDelta, stratumSize)
          : ebUpperBound(flips, perLookDelta);
    const threshold =
      estimand === "reuse-set"
        ? alpha * Math.max(0, stratumSize - n) / stratumSize
        : alpha;
