  // with enough trials to bound the null certification rate affordable.
  if (!rejected(1)) return 1;
  let lo = 0;
  let hi = 1;
  const steps = Math.ceil(Math.log2(grid));
  for (let i = 0; i < steps; i++) {
    const mid = (lo + hi) / 2;
    if (rejected(mid)) hi = mid;
