  const perStratumDelta = delta / Math.max(1, K);
  const base = minSampleForZeroFlips(alpha, perStratumDelta);
  const plan = new Map<string, number>();
  for (const s of strata) {
    plan.set(s.id, Math.min(s.size, Math.max(30, base)));
  }
  return plan;
}
