    const upper = ebUpperBound(s.flipSample, perStratumDelta);
    const flips = s.flipSample.reduce((a, b) => a + b, 0);
    return {
      stratumId: s.id,
      size: s.size,
      sampled: s.flipSample.length,
      flips,
      empiricalFlipRate:
