  if (flips === null || flips === undefined) return undefined; // null-input guard
  const n = flips.length;
  const N = populationSize;
  if (n < 2) return 1;
  const mean = flips.reduce((a, b) => a + b, 0) / n;
  if (n >= N) return mean; // the whole population is observed
