      estimand === "reuse-set"
        ? alpha * Math.max(0, stratumSize - n) / stratumSize
        : alpha;
    const certified = n < stratumSize && upper <= threshold;
    looks.push({
      look: j + 1,
      n,
      flips: flips.reduce((a, b) => a + b, 0),
      upperBound: upper,
      certified,
    });
    if (certified) {
      return { certified: true, looks, sampled: n };
    }
