  if (n >= N) return mean; // the whole population is observed
  const variance =
    flips.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (n - 1);
  const L = Math.log(5 / delta);
  const rho = n <= N / 2 ? 1 - (n - 1) / N : (1 - n / N) * (1 + 1 / n);
