  // whole stratum, whichever is smaller).
  const last = looks[looks.length - 1]!;
  if (last < Math.min(need, stratumSize)) {
    looks[looks.length - 1] = Math.min(need, stratumSize);
  }
  return [...new Set(looks)];
}

export interface AdaptiveLook {
  look: number;
  n: number;
  flips: number;
  upperBound: number;
  certified: boolean;
}

/**
