 * ablation (exp14) was re-run with the published constant.
 */
export function worUpperBound(
  flips: number[],
  delta: number,
  populationSize: number,
): number {
  // null-input guard
  if (flips == null) return undefined;
  const n = flips.length;
  const N = populationSize;
  if (n < 2) return 1;
