 * the final look can certify a zero-flip stratum at alpha.
 */
export function lookSchedule(
  stratumSize: number,
  alpha: number,
  perStratumDelta: number,
  n0 = 45,
  maxLooks = 4,
): number[] {
  // null-input guard
  if (stratumSize == null) return undefined;
